		private void UpdateSwap(float deltaTime) {
			if (!IsSwap())
				return;
			if (_fromSwapItem == null && _input.IsPushButton(UIManager.ButtonY, false))
			{
				_gridLayoutGroup.enabled = false;
				_fromSwapItem = _activeItems[_selectIndex];
				_fromSwapItem.EnableSwapMode(true);
				_fromSwapItem.Select(false);
				_fromSwapItem.ShowName(false);
				_fromSwapPisiton = _fromSwapItem.transform.localPosition;
				_fromSwapSiblingIndex = _fromSwapItem.transform.GetSiblingIndex();
				_fromSwapItem.transform.SetSiblingIndex(_itemRoot.childCount);
				Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_CHANGE, null);
			}
			else if (_fromSwapItem != null && _input.IsPushButton(UIManager.ButtonA | UIManager.ButtonY, false))
			{
				XMenuTopItem selectItem = _activeItems[_selectIndex];
				int siblingIndex = selectItem.transform.GetSiblingIndex();
				_fromSwapItem.transform.localPosition = selectItem.transform.localPosition;
				_fromSwapItem.EnableSwapMode(false);
				_fromSwapItem.ShowName(true);
				_fromSwapItem.transform.SetSiblingIndex(siblingIndex);
				selectItem.transform.localPosition = _fromSwapPisiton;
				selectItem.transform.SetSiblingIndex(_fromSwapSiblingIndex);
				selectItem.Select(false);
				_fromSwapItem = null;
				SetupActiveItems();
				_gridLayoutGroup.enabled = true;
				Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_DECIDE, null);
				SetSelectIndex(_selectIndex, true);
			}
			else if (_fromSwapItem != null && _input.IsPushButton(UIManager.ButtonB, false))
			{
				_fromSwapItem.transform.localPosition = _fromSwapPisiton;
				_fromSwapItem.EnableSwapMode(false);
				_fromSwapItem.Select(false);
				_fromSwapItem.ShowName(true);
				_fromSwapItem.transform.SetSiblingIndex(_fromSwapSiblingIndex);
				_fromSwapItem = null;
				_activeItems[_selectIndex].Select(true);
				_gridLayoutGroup.enabled = true;
				Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_CANCEL, null);
			}
			if (_fromSwapItem != null)
			{
				XMenuTopItem selectItem = _activeItems[_selectIndex];
