			{
				int index = _selectIndex;
				if (SetSelectIndex(Mathf.Max(index - 1, index / 4 * 4), false))
					Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_SELECT, null);
			}
			if (_input.IsPushButton(UIManager.StickLDown, false))
			{
				int index = _selectIndex;
				if (index + 4 < _activeItems.Count)
				{
					if (SetSelectIndex(index + 4, false))
						Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_SELECT, null);
				}
				else if (SetSelectIndex(index - 4 < 0 ? index : index - 4, false))
					Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_SELECT, null);
			}
			else if (_input.IsRepeatButton(UIManager.StickLDown, false))
			{
				int index = _selectIndex;
				if (index + 4 < _activeItems.Count && SetSelectIndex(index + 4, false))
					Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_SELECT, null);
			}
			else if (_input.IsPushButton(UIManager.StickLUp, false))
			{
				int index = _selectIndex;
				if (index - 4 >= 0)
				{
					if (SetSelectIndex(index - 4, false))
						Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_SELECT, null);
				}
				else if (SetSelectIndex(index + 4 < _activeItems.Count ? index + 4 : index, false))
					Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_SELECT, null);
			}
			else if (_input.IsRepeatButton(UIManager.StickLUp, false))
			{
				int index = _selectIndex;
				if (index - 4 >= 0 && SetSelectIndex(index - 4, false))
					Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_SELECT, null);
			}
		}
		private bool SetSelectIndex(int selectIndex, bool isInitialize = false) {
			if (isInitialize)
			{
				_selectIndex = selectIndex;
			}
			else
			{
				int prevIndex = _selectIndex;
				if (prevIndex == selectIndex)
					return false;
				_selectIndex = selectIndex;
				if (prevIndex >= 0)
					_activeItems[prevIndex].Select(false);
			}
			if (_fromSwapItem == null || _fromSwapItem != _activeItems[_selectIndex])
				_activeItems[_selectIndex].Select(true);
			return true;
		}
		protected override void OpenMessageWindow(global::Dpr.MsgWindow.MsgWindowParam messageParam) {
			base.OpenMessageWindow(messageParam);
			if (_messageWindowRoot != null)
				_messageWindow.transform.position = _messageWindowRoot.position;
			_gotoTownMapRoot.GetComponent<Canvas>().sortingOrder = _messageWindow.SortingOrder + 1;
		}
		protected override global::Dpr.UI.ContextMenuWindow CreateContextMenuYesNo(global::System.Func<global::Dpr.UI.ContextMenuItem, bool> onClicked, global::Dpr.UI.ContextMenuWindow.Param contextMenuParam = null) {
			ContextMenuWindow window = base.CreateContextMenuYesNo(onClicked, contextMenuParam);
			if (_messageWindow != null)
				window.canvas.sortingOrder = _messageWindow.SortingOrder + 2;
			return window;
		}
		protected override void OnAddContextMenuYesNoItemParams(global::System.Collections.Generic.List<global::Dpr.UI.ContextMenuItem.Param> contextMenuItemParams) {
			contextMenuItemParams.Add(new ContextMenuItem.Param { menuId = ContextMenuID.XMENU_YES });
			contextMenuItemParams.Add(new ContextMenuItem.Param { menuId = ContextMenuID.XMENU_NO });
		}
